function decData(){const s=snap(),m=mc(),cw=commitWd(),p80=m.q("beta",.8),pr=m.pr("beta",cw),L=s.L,d3=L.find(d=>d.id==="D3"),line=L.filter(d=>d.fund).slice(-1)[0],rec=appRecs().filter(r=>r.k==="Retire"),sv=rec.reduce((a,r)=>a+r.save,0);
 const T={
 d1:{t:"Approve the $48,000 reforecast for cloud hosting",d:`Moves contingency to cover a larger Northwind tier. Forecast is ${METRICS.m_burn.cur}% of approved. Forecast Agent drafted it.`,amt:"$48K",ai:{model:"Forecast Agent",conf:.86,src:["B1 FY26 Cloud hosting","Northwind usage report","KB-114"]}},
 d2:{t:"Hold the Lumen payment of $62,900 (INV-20433)",d:"Milestone 3 is not accepted and $412,000 is already paid against $390,000 accepted. Invoice Advisor recommends holding.",amt:"$62.9K",ai:{model:"GPT (council)",conf:.81,src:["INV-20433","PO-77120","Acceptance record"]}},
 d3:{t:"Fund the lease subledger retirement (D3, $680K)",d:`D3 scores ${d3?d3.score:77}${line?`, just under the funding line at ${line.score}`:""}. The Standard 842 amendment takes effect Jan 1, 2027, and the old subledger cannot support it.`,amt:"$680K",ai:{model:"Portfolio Agent",conf:.78,src:["Demand scoring","Knowledge graph impact analysis Standard 842"]}},
 d4:{t:`Commit to ${dstr(p80)} as the Standards beta date`,d:`${Math.round(pr*100)}% chance of landing by ${dstr(cw)}; 80% by ${dstr(p80)}. The plan date is ${dstr(s.beta)} and the baseline was ${dstr(s.bBeta)}.`,amt:dstr(p80),ai:{model:"Monte Carlo (2,000 trials)",conf:.8,src:["Master schedule","Risk register","Lumen history"]}},
 d5:{t:"Approve the Portal failover rehearsal, Sat Oct 24 02:00",d:"A tested failover is the fix for Tier 1 availability of 99.62%. Needs a two-hour maintenance window and Ops team overtime.",amt:"2 h window",ai:{model:"Ops Agent",conf:.9,src:["RB-031","INC1","Change calendar"]}},
 d6:{t:"Pause expansion of the AI drafting assistant until overrides drop",d:`Agents are overridden ${METRICS.m_override.cur}% of the time against a 10% target. Four of six Lumen holds were overridden. Existing agents keep running.`,amt:METRICS.m_override.cur+"%",ai:{model:"Feedback Analyst",conf:.84,src:["Override log","Control Tower"]}},
 d7:{t:`Retire ${rec.length} duplicate or failing applications, saving $${sv}K a year`,d:"AI reviewed cost, use and overlap. Each retirement has an owner and a 4 to 8 week plan in the application portfolio.",amt:"$"+sv+"K",ai:{model:"Claude Sonnet",conf:.85,src:["Application inventory","Usage","Redundancy map"]}}};
 return DEC0.map(x=>({...x,...T[x.id]}))}
function pendAge(){const p=DEC0.filter(x=>!E.dec[x.id]);return p.length?p.reduce((s,x)=>s+x.since,0)/p.length:0}

