const trn=(a,c)=>a.concat([c]);
Object.assign(METRICS,{
 m_align:{n:"Strategic alignment score",f:"Funded dollars linked to an objective ÷ All funded dollars × 100, minus 8 points for each objective with no funded work",u:"pts",cur:89,tgt:90,badAt:80,dir:"max",max:100,tr:trn([84,85,86,86,87,88,88],89),owner:"Portfolio office",use:["Strategy alignment","Executive dashboard","Board pack"],rem:{kind:"sop",ref:"SOP-410",title:"Re-link or stop unaligned work",agent:"Portfolio Agent",auto:false,state:"idle",prog:"Lists funded work with no objective and objectives with no funded work"}},
 m_riskexp:{n:"Risk exposure against contingency",f:"Σ (Probability × Impact in dollars) ÷ Contingency reserve (10% of approved budget)",u:"%",cur:90,tgt:70,badAt:100,dir:"min",max:150,tr:trn([58,62,71,75,80,85,88],90),owner:"PMO",use:["Risk heat map","Executive dashboard","Board pack"],rem:{kind:"kb",ref:"KB-131",title:"Cover or release contingency",agent:"Forecast Agent",auto:false,state:"idle",prog:"Proposes mitigations ranked by exposure removed per dollar"}},
 m_conf:{n:"Beta date confidence",f:"Monte Carlo trials that finish the beta milestone on or before the committed date ÷ All trials",u:"%",cur:60,tgt:80,badAt:60,dir:"max",max:100,tr:trn([92,90,86,82,78,74,72],70),owner:"PMO",use:["Risk heat map","Executive dashboard","Scenario compare"],rem:{kind:"sop",ref:"SOP-211",title:"Rebuild schedule confidence",agent:"PMO Agent",auto:true,state:"running",prog:"Testing a two-engineer Lumen crash against the committed date"}},
 m_waste:{n:"Application spend to retire or move",f:"Annual cost of applications classed Eliminate, plus duplicates ÷ Total application cost",u:"%",cur:5.2,tgt:5,badAt:12,dir:"min",max:30,tr:trn([14,13.8,13,12.5,12,11,10.6],5.2),owner:"Architecture",use:["Application portfolio","Executive dashboard"],rem:{kind:"agent",ref:"Portfolio Agent",title:"Draft retirement plans",agent:"Portfolio Agent",auto:false,state:"idle",prog:"Drafts a plan per application with users to move and a date"}},
 m_decage:{n:"Executive decision age",f:"Average days since a decision was requested, for decisions not yet made",u:"days",cur:3.2,tgt:3,badAt:5,dir:"min",max:10,tr:trn([2.1,2.4,2.8,3,3.4,3.6,3.3],3.2),owner:"Executive office",use:["Executive dashboard","Board pack"],rem:{kind:"agent",ref:"First Officer",title:"Remind decision owners",agent:"First Officer",auto:true,state:"running",prog:"Sent two nudges this week"}}});
function sync(){const s=snap(),c=coverage(),st=appStats(),m=mc();
 METRICS.m_align.cur=Math.round(c.score*10)/10;METRICS.m_riskexp.cur=Math.round(s.exposure/s.contingency*100);METRICS.m_conf.cur=Math.round(m.pr("beta",commitWd())*100);METRICS.m_waste.cur=Math.round(st.pct*10)/10;METRICS.m_decage.cur=Math.round(pendAge()*10)/10;
 ["m_align","m_riskexp","m_conf","m_waste","m_decage"].forEach(k=>{METRICS[k].tr[7]=METRICS[k].cur});if(window.MAT&&MAT.sync)MAT.sync()}

/* ---------------- shared UI ---------------- */
const stTxtX=s=>s==="good"?"On track":s==="warn"?"Watch":"Needs action";
const stPill=s=>pill(stTxtX(s),s);
const goB=(g,t,cls)=>`<button class="btn ${cls||"quiet"}" data-go="${g}">${t}</button>`;
function etile(o){const st=o.st||"good";
 return `<div class="exe-tile tile glass" data-st="${st}"><button class="exe-tgo" data-go="${o.go}" aria-label="Open ${esc(o.l)} in its source screen"><span class="lbl">${esc(o.l)}</span><span class="big num" data-role="metric">${o.v}</span><span class="delta ${st}" data-role="story">${o.sub}</span></button><div class="row exe-tf">${o.m?fchip(o.m,"Formula"):""}<span class="exe-open">${esc(o.goL||"Open")} <i aria-hidden="true">→</i></span></div></div>`}
const mTile=(id,l,go,sub,v)=>{const m=METRICS[id];return etile({l:l||m.n,v:v!=null?v:mfmt(m),sub:sub||`Target ${m.dir==="max"?"at least":"at most"} ${mfmt(m,m.tgt)}`,st:mstat(m),m:id,go})};
function capPeak(s){const g=load(s.P,s.extra);let best={v:0};Object.keys(g).forEach(t=>g[t].forEach((v,i)=>{if(i>=3&&i<=6&&v>best.v)best={v,team:t,mo:MONTHS[i][0]}}));return best}
const topRisks=n=>E.risks.filter(r=>r.st!=="Closed").slice().sort((a,b)=>rX(b)-rX(a)).slice(0,n);
const dateIso=wd=>dateOf(wd).toISOString().slice(0,10);

/* ---------------- charts, all drawn to one scale ---------------- */
function slipChart(s){const rows=[["Standards beta",s.bBeta,s.beta,"p1_5"],["Standards go live",s.bLive,s.live],["Taxonomy pilot",BASE.R.p2_5.ef,s.pilot],["Sev 2 problem closed",BASE.R.p3_5.ef,s.sev2]],W=640,H=40+rows.length*42,L=150,R=22,lo=60,hi=130,xs=w=>L+(W-L-R)*(w-lo)/(hi-lo);let g="";
 for(let w=lo;w<=hi;w+=10)g+=`<line class="grid-l" x1="${xs(w)}" x2="${xs(w)}" y1="14" y2="${H-26}"/><text class="ax" x="${xs(w)}" y="${H-8}" text-anchor="middle">${dstr(w)}</text>`;
 g+=`<line x1="${xs(TODAY)}" x2="${xs(TODAY)}" y1="10" y2="${H-26}" stroke="var(--ink)" stroke-width="1.6" stroke-dasharray="4 4"/><text class="ax" x="${xs(TODAY)+4}" y="22">Today</text>`;
 rows.forEach((r,i)=>{const y=44+i*42,late=r[2]>r[1];g+=`<text class="ax" x="8" y="${y+4}" style="fill:var(--ink);font-size:12.5px">${r[0]}</text><line x1="${xs(r[1])}" x2="${xs(r[2])}" y1="${y}" y2="${y}" stroke="${col(late?"--warn-f":"--good-f")}" stroke-width="5" stroke-linecap="round" opacity=".55"/><circle cx="${xs(r[1])}" cy="${y}" r="6" fill="var(--bg)" stroke="var(--muted)" stroke-width="2"/><circle cx="${xs(r[2])}" cy="${y}" r="7" fill="${col(late?"--warn-f":"--good-f")}" stroke="var(--bg)" stroke-width="2"/><text class="ax" x="${xs(Math.max(r[1],r[2]))+12}" y="${y+4}" style="fill:var(--ink)">${dstr(r[2])}${late?` (+${r[2]-r[1]} days)`:""}</text>`});
 return `<svg class="chart" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Baseline and forecast dates for four milestones">${g}</svg>`}
/* PR-24: a project with no plan in the snapshot (for example added by Self-build) is drawn with no earned value, never an invented one */
function spendChart(s){const rows=PROJ.map(p=>({p,ev:(s.ev[p.id]||{ev:0}).ev})),W=640,L=118,R=70,H=34+rows.length*46,mx=1300,xs=v=>L+(W-L-R)*v/mx;let g="";
 [0,300,600,900,1200].forEach(v=>{g+=`<line class="grid-l" x1="${xs(v)}" x2="${xs(v)}" y1="8" y2="${H-24}"/><text class="ax" x="${xs(v)}" y="${H-8}" text-anchor="middle">${v?K$(v):"$0"}</text>`});
 rows.forEach((r,i)=>{const y=14+i*46,p=r.p;g+=`<text class="ax" x="6" y="${y+14}" style="fill:var(--ink);font-size:12.5px">${esc(p.short)}</text><rect x="${L}" y="${y}" width="${xs(p.bac)-L}" height="14" rx="7" fill="var(--track)"/><rect x="${L}" y="${y}" width="${Math.max(2,xs(p.paid)-L)}" height="14" rx="7" fill="${col("--p4")}"/><line x1="${xs(p.bac*r.ev)}" x2="${xs(p.bac*r.ev)}" y1="${y-4}" y2="${y+18}" stroke="${col("--metric-f")}" stroke-width="3" stroke-linecap="round"/><text class="ax" x="${xs(p.bac)+8}" y="${y+12}" style="fill:var(--ink)">${K$(p.bac)}</text><text class="ax" x="${L}" y="${y+30}">paid ${K$(p.paid)} · earned ${K$(Math.round(p.bac*r.ev))}</text>`});
 return `<svg class="chart" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Approved, paid and earned value for each project"><g>${g}</g></svg><div class="row exe-leg"><span><i style="background:var(--track)"></i>Approved</span><span><i style="background:var(--p4)"></i>Paid</span><span><i style="background:var(--metric-f)"></i>Work earned (planned effort completed)</span></div>`}
function capHeat(s){const g=load(s.P,s.extra),cols=[3,4,5,6];return `<div class="exe-heat" style="--cols:${cols.length}"><span></span>${cols.map(i=>`<b>${MONTHS[i][0]}</b>`).join("")}${Object.keys(g).map(t=>`<span class="exe-ht">${esc(t)}</span>${cols.map(i=>{const v=g[t][i],c=v>1.05?"bad":v>.85?"warn":"good";return `<i class="${c}" data-role="metric">${Math.round(v*100)}%</i>`}).join("")}`).join("")}</div>`}
function objBar(o){const p=objProg(o),c=coverage().res[o.id];return `<button class="exe-obj" data-go="exe_strat" aria-label="Open ${esc(o.n)}"><span class="exe-on"><i style="background:${col(o.c)}"></i><b>${esc(o.n)}</b></span><span class="exe-bar" title="Progress ${Math.round(p.p*100)}%, expected ${Math.round(p.e*100)}% by today"><u style="width:${Math.round(p.p*100)}%;background:${col(SC[p.st])}"></u><s style="left:${Math.round(p.e*100)}%"></s></span><span class="exe-ob2">${stPill(p.st)}<small class="muted" data-role="metric">${Math.round(p.p*100)}% · ${c.fund?K$(Math.round(c.fund)):"no funded work"}</small></span></button>`}

