 ai:()=>{const ag=AGENTS,sp=ag.reduce((a,b)=>a+b.spend,0),cp=ag.reduce((a,b)=>a+b["cap$"],0),hits=ag.reduce((a,b)=>a+b.hits,0);return card("AI spend and governance",`${AGENTS.filter(a=>a.st!=="observed").length} of ${AGENTS.length} agents run through the gateway. Copilot in Teams is observed only.`,`<dl class="kv exe-kv"><dt>Spend today</dt><dd class="num" data-role="metric">$${sp.toFixed(2)} of $${cp} cap (${Math.round(sp/cp*100)}%)</dd><dt>Override rate</dt><dd class="num" data-role="metric" style="color:${col(SC[mstat(METRICS.m_override)])}">${METRICS.m_override.cur}% (target 10%)</dd><dt>Guardrail hits</dt><dd data-role="metric">${hits} this week, all blocked</dd><dt>30-day trend</dt><dd>${spark(SPEND30,200,36,col("--p4"))}</dd></dl><div class="row">${fchip("m_override")}${fchip("m_aispend")}${goB("tower","Control Tower")}</div>`)},
 apps:()=>{const st=appStats(),tt=st.total;return card("Application portfolio",`${money(tt*1000)} a year across ${E.apps.length} applications. ${Math.round(st.pct*10)/10}% ($${st.waste}K) is duplicated or failing.`,`<div class="exe-split">${TIMES.map(t=>`<i style="flex:${Math.max(.5,st.by[t[0]])};background:${col(t[2])}" title="${t[0]} ${K$(st.by[t[0]])}"></i>`).join("")}</div><div class="row exe-leg">${TIMES.map(t=>`<span><i style="background:${col(t[2])}"></i>${t[0]} <b data-role="metric">${K$(st.by[t[0]])}</b></span>`).join("")}</div><div class="row">${fchip("m_waste")}${goB("exe_apps","Open portfolio")}</div>`)},
