 mat:()=>{if(!window.MAT)return "";const rows=MAT.objRollRows();return card("Maturity against strategy",`${MAT.ALLM().length} maturity models, ${MAT.leaves().length} capabilities. Attainment ${METRICS.m_matatt.cur}% against the Year 1 target; glide-path index ${METRICS.m_matgp.cur}.`,`<div class="exe-objs">${rows.map(({o,R:r})=>`<button class="exe-obj" data-go="exe_mat" aria-label="Open maturity for ${esc(o.n)}"><span class="exe-on"><i style="background:${col(o.c)}"></i><b>${esc(o.sub||o.n)}</b></span><span class="exe-bar" role="img" aria-label="Level ${MAT.fv(r.cur)} of 5, Year 1 target ${MAT.fv(r.t1)}"><u style="width:${Math.min(100,r.cur/5*100)}%;background:${col(r.st==="good"?"--good-f":r.st==="warn"?"--warn-f":"--bad-f")}"></u><s style="left:${Math.min(100,r.t1/5*100)}%"></s></span><span class="exe-ob2"><span class="num" data-role="metric">${r.n?MAT.fv(r.cur):"none"}</span>${r.n?MAT.stPill(r.st):pill("No capabilities","mute")}</span></button>`).join("")}</div><div class="row">${fchip("m_matatt")}${fchip("m_matgp")}${fchip("m_matcov")}${goB("exe_mat","Open maturity models")}</div>`)},
